-- evt:thing:town_well
RegisterEvent(56, "Well", function()
    if not (IsQBitSet(QBit(112141))) then
        evt.PlaySoundName("xeen_well_drink")
        evt.StatusText("The water is black and tastes of iron. You decide you are not thirsty.", 6)
        return
    end
    evt.PlaySoundName("xeen_well_drink")
    evt.ForPlayer(Players.All)
    SubtractValue(DiseasedGreen, 0)
    SubtractValue(DiseasedYellow, 0)
    SubtractValue(DiseasedRed, 0)
    SubtractValue(Weak, 0)
    if Xeen.usedToday("x3_town_well") then evt.StatusText("The water is cool and refreshing.") else Xeen.markToday("x3_town_well") AddValue(PersonalityBonus, 10) evt.StatusText("The water is clear and cold, and tastes faintly of garlic. You feel healthier, and somehow more likeable. (+10 Personality until you rest)") end
end, "Well")

